class TokenizerUnavailable(RuntimeError):
    """Raised when exact server tokenization cannot be obtained."""


class RequestBudgetExceeded(RuntimeError):
    """Raised before a model request when its exact token count is too large."""


class RequestFailure(RuntimeError):
    """Raised when prompt preparation or model transport fails with evidence."""

    def __init__(self, phase, message, evidence=None):
        super().__init__(message)
        self.phase = phase
        self.evidence = evidence or {}


def ensure_dir(path):
    os.makedirs(path, exist_ok=True)


def safe_json(value: Any) -> Any:
    try:
        json.dumps(value)
        return value
    except TypeError:
        return repr(value)


class Journal:
    def __init__(self, root: Path):
        self.root = Path(root)
        ensure_dir(self.root)
        self.events = self.root / "events.jsonl"
        self.state_file = self.root / "state.json"
        self.lock_file = self.root / ".journal.lock"
        self.events.touch(exist_ok=True)
        self.thread_lock = threading.RLock()
        self.records = self._read_and_repair()

    def _locked(self):
        journal = self

        class Lock:
            fd = None

            def __enter__(inner):
                inner.fd = os.open(journal.lock_file, os.O_RDWR | os.O_CREAT, 0o600)
                fcntl.flock(inner.fd, fcntl.LOCK_EX)
                return inner

            def __exit__(inner, *_):
                fcntl.flock(inner.fd, fcntl.LOCK_UN)
                os.close(inner.fd)

        return Lock()

    def _read_and_repair(self):
        if not self.events.exists():
            return []
        with self._locked():
            return self._read_and_repair_unlocked()

    def _read_and_repair_unlocked(self):
        good = []
        valid_end = 0
        with self.events.open("rb") as stream:
            while True:
                line = stream.readline()
                if not line:
                    break
                try:
                    item = json.loads(line.decode("utf-8"))
                except (UnicodeDecodeError, json.JSONDecodeError):
                    break
                if not isinstance(item, dict):
                    break
                good.append(item)
                valid_end = stream.tell()
        with self.events.open("r+b") as stream:
            stream.truncate(valid_end)
            stream.flush()
            os.fsync(stream.fileno())
        return good

    def latest_snapshot(self):
        return next((record["payload"] for record in reversed(self.records) if record.get("kind") == "state_snapshot" and isinstance(record.get("payload"), dict)), None)

    def load_state(self):
        try:
            with self.state_file.open(encoding="utf-8") as stream:
                value = json.load(stream)
            return value if isinstance(value, dict) else self.latest_snapshot()
        except (OSError, json.JSONDecodeError):
            return self.latest_snapshot()

    def transaction(self, kind: str, payload: Any, state: dict[str, Any]):
        raw_state = json.dumps(state, ensure_ascii=False, sort_keys=True)
        with self.thread_lock, self._locked():
            self.records = self._read_and_repair_unlocked()
            seq = (self.records[-1].get("seq", 0) if self.records else 0) + 1
            entries = [{"seq": seq, "time": time.time(), "kind": kind, "payload": safe_json(payload)}, {"seq": seq + 1, "time": time.time(), "kind": "state_snapshot", "payload": json.loads(raw_state)}]
            with self.events.open("ab") as stream:
                for entry in entries:
                    stream.write((json.dumps(entry, ensure_ascii=False, sort_keys=True) + "\n").encode())
                stream.flush()
                os.fsync(stream.fileno())
            fd, temporary = tempfile.mkstemp(prefix="state.", dir=self.root)
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as stream:
                    stream.write(raw_state + "\n")
                    stream.flush()
                    os.fsync(stream.fileno())
                os.replace(temporary, self.state_file)
            finally:
                if os.path.exists(temporary):
                    os.unlink(temporary)
            self.records.extend(entries)

    def event(self, kind: str, payload: Any):
        with self.thread_lock, self._locked():
            self.records = self._read_and_repair_unlocked()
            seq = (self.records[-1].get("seq", 0) if self.records else 0) + 1
            entry = {"seq": seq, "time": time.time(), "kind": kind, "payload": safe_json(payload)}
            with self.events.open("ab") as stream:
                stream.write((json.dumps(entry, ensure_ascii=False) + "\n").encode())
                stream.flush()
                os.fsync(stream.fileno())
            self.records.append(entry)


def proc_identity(pid: int):
    base = Path("/proc") / str(pid)
    try:
        stat = (base / "stat").read_text()
        fields = stat[stat.rfind(")") + 2 :].split()
        # /proc/[pid]/stat field 22 is starttime.  After removing pid/comm,
        # it is index 19 (22 - the three leading stat fields).
        starttime = fields[22 - 3]
        return {"pid": pid, "boot_id": Path("/proc/sys/kernel/random/boot_id").read_text().strip(), "starttime": starttime, "state": fields[0], "command": (base / "cmdline").read_bytes().replace(b"\0", b" ").decode(errors="replace").strip(), "cwd": os.readlink(base / "cwd")}
    except (OSError, IndexError):
        return None


def identity_matches(expected, actual):
    return bool(actual and expected.get("boot_id") == actual.get("boot_id") and expected.get("starttime") == actual.get("starttime"))


class SearchParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.results = []
        self.current = None
        self.snippet = False

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "a" and "result__a" in attrs.get("class", ""):
            self.current = {"title": "", "url": attrs.get("href", ""), "snippet": ""}
        if "result__snippet" in attrs.get("class", ""):
            self.snippet = True

    def handle_data(self, data):
        if self.current:
            self.current["title"] += data.strip() + " "
        if self.snippet and self.current:
            self.current["snippet"] += data.strip() + " "

    def handle_endtag(self, tag):
        if self.snippet and tag in {"a", "div"}:
            self.snippet = False
        if tag == "a" and self.current and self.current["title"].strip():
            self.results.append({key: value.strip() for key, value in self.current.items()})
            self.current = None


class EchoAgent:
    def __init__(self, server=DEFAULT_SERVER, root=DEFAULT_ROOT, session=None, caller_task_id=None, role=None, subagent_role=None, review_of=None, review_revision=None, source_order=None, source_metadata=None, task_order=None, spawn_instance_id=None, inherited_read_only=False, inherited_web_forbidden=False, required_reads=None, auto_finish_required_io=False, auto_finish_acceptance_binding=None):
        self.server = server.rstrip("/")
        self.journal = Journal(Path(root))
        saved = self.journal.load_state()
        self.state = saved or {"session_id": session or uuid.uuid4().hex, "objective": "", "messages": [], "pending_user": [], "pending_tool_calls": [], "completed_tool_calls": [], "active_processes": {}, "completed": False, "pause": False, "shutdown": False, "last_tool_signature": None, "working_state": {"summary": "", "facts": [], "pending_steps": [], "failures": [], "artifacts": []}, "result_sequence": 0, "request_errors": [], "source_order": source_order, "source_metadata": source_metadata or {}, "task_order": task_order, "spawn_instance_id": spawn_instance_id}
        self.state.setdefault("last_tool_signature", None)
        self.state.setdefault("working_state", {"summary": "", "facts": [], "pending_steps": [], "failures": [], "artifacts": []})
        self.state.setdefault("result_packages", [])
        if isinstance(self.state.get("result_groups"), list):
            self.state["result_groups"] = {item.get("group_id"): item for item in self.state["result_groups"] if item.get("group_id")}
        self.state.setdefault("result_groups", {})
        self.state.setdefault("result_group_error", None)
        self.state.setdefault("result_sequence", 0)
        self.state.setdefault("request_errors", [])
        self.state.setdefault("required_writes", [])
        self.state.setdefault("required_reads", safe_json(required_reads or []))
        if required_reads is not None:
            self.state["required_reads"] = safe_json(required_reads)
        self.state.setdefault("execution_phase", None)
        self.state.setdefault("subagents", {})
        self.state.setdefault("subagent_result", None)
        self.state.setdefault("context_tokens", DEFAULT_CONTEXT_TOKENS)
        self.state.setdefault("caller_task_id", caller_task_id)
        self.state.setdefault("role", role or ("subagent" if caller_task_id else "subagent"))
        self.state.setdefault("subagent_role", subagent_role or "subagent")
        self.state.setdefault("review_of", review_of)
        self.state.setdefault("review_revision", review_revision)
        self.state.setdefault("source_order", source_order)
        self.state.setdefault("source_metadata", source_metadata or {})
        self.state.setdefault("task_order", task_order)
        self.state.setdefault("spawn_instance_id", spawn_instance_id)
        self.state.setdefault("required_write_targets", [])
        self.state.setdefault("acceptance_runs", [])
        self.state.setdefault("acceptance_spec", self._acceptance_spec([]))
        self.state.setdefault("auto_finish_required_io", bool(auto_finish_required_io))
        self.state.setdefault("auto_finish_acceptance_binding", {})
        self.state.setdefault("auto_finish_identity", None)
        if auto_finish_required_io:
            self.state["auto_finish_required_io"] = True
        if isinstance(auto_finish_acceptance_binding, dict) and auto_finish_acceptance_binding:
            self.state["auto_finish_acceptance_binding"] = safe_json(auto_finish_acceptance_binding)
        if source_order is not None:
            self.state["source_order"] = source_order
        if source_metadata is not None:
            self.state["source_metadata"] = source_metadata
        if task_order is not None:
            self.state["task_order"] = task_order
        if spawn_instance_id is not None:
            self.state["spawn_instance_id"] = spawn_instance_id
        for optional_key in ("review_revision", "source_order", "task_order"):
            try:
                self.state[optional_key] = optional_int(self.state.get(optional_key))
            except (TypeError, ValueError):
                self.state[optional_key] = None
        self.state.setdefault("review_gate", "pending")
        self.state.setdefault("stale_reviews", [])
        self.state.setdefault("terminal", False)
        self.state.setdefault("success", False)
        self.state.setdefault("revision", 0)
        self.state.setdefault("non_idempotent_calls", {})
        existing_policy = self.state.get("task_policy") if isinstance(self.state.get("task_policy"), dict) else None
        inherited_from_state = bool(existing_policy and (existing_policy.get("inherited_read_only") or existing_policy.get("matched_rule") == "inherited_read_only"))
        inherited_web_from_state = bool(existing_policy and (existing_policy.get("inherited_web_forbidden") or existing_policy.get("network_matched_rule") == "inherited_web_forbidden"))
        self.inherited_read_only = bool(inherited_read_only or inherited_from_state)
        self.inherited_web_forbidden = bool(inherited_web_forbidden or inherited_web_from_state)
        policy_missing = existing_policy is None
        policy_upgraded = False
        if policy_missing:
            self.state["task_policy"] = self._derive_task_policy(self.state.get("objective", ""), inherited_read_only=self.inherited_read_only, inherited_web_forbidden=self.inherited_web_forbidden)
        elif "web_forbidden" not in existing_policy or (self.inherited_read_only and not existing_policy.get("read_only")) or (self.inherited_web_forbidden and not existing_policy.get("web_forbidden")):
            upgraded = self._derive_task_policy(self.state.get("objective", ""), inherited_read_only=self.inherited_read_only, inherited_web_forbidden=self.inherited_web_forbidden)
            transitions = []
            if self.inherited_read_only and not existing_policy.get("read_only"):
                transitions.append("inherited_read_only_upgrade")
            if self.inherited_web_forbidden and not existing_policy.get("web_forbidden"):
                transitions.append("inherited_web_forbidden_upgrade")
            if "web_forbidden" not in existing_policy:
                transitions.append("network_policy_migration")
            upgraded["transition"] = "inherited_upgrade" if transitions == ["inherited_read_only_upgrade"] else "+".join(transitions)
            upgraded["previous_mode"] = existing_policy.get("mode", "write_allowed")
            upgraded["previous_network_mode"] = existing_policy.get("network_mode", "web_allowed")
            self.state["task_policy"] = upgraded
            policy_upgraded = True
        if session and self.state.get("session_id") != session:
            raise ValueError("İstenen oturum bulunamadı")
        self._normalize_required_write_targets()
        self._normalize_required_writes()
        self._normalize_required_reads()
        if self.state.get("execution_phase") not in {NEED_REQUIRED_WRITE, NEED_REQUIRED_READ, NEED_FINISH}:
            self._refresh_required_read_phase()
        self.process_handles = {}
        self.condition = threading.Condition()
        self.connection_lock = threading.RLock()
        self.active_connection = None
        self.wake_requested = threading.Event()
        self.tree_cleanup_lock = threading.RLock()
        self.tree_cleanup_active = False
        self._persist("restore", {"session_id": self.state["session_id"]})
        if policy_missing or policy_upgraded:
            self._persist("task_policy", self.state["task_policy"])

    def _persist(self, kind, payload):
        self.journal.transaction(kind, payload, self.state)

    def _message(self, message):
        self.state["messages"].append(message)
        self._persist("message", message)

    @staticmethod
    def _contract_text(text):
        value = str(text)
        value = re.sub(r"```.*?```|~~~.*?~~~", " ", value, flags=re.DOTALL)
        value = re.sub(r"`[^`\n]*`|\"(?:\\.|[^\"\\])*\"|'(?:\\.|[^'\\])*'|“[^”]*”|‘[^’]*’", " ", value, flags=re.DOTALL)
        value = "\n".join("" if line.lstrip().startswith(">") else line for line in value.splitlines())
        normalized = unicodedata.normalize("NFKD", value.casefold())
        normalized = "".join(character for character in normalized if not unicodedata.combining(character))
        return normalized.translate(str.maketrans({"ı": "i"}))

    @staticmethod
    def _objective_acceptance_commands(objective):
        prefix = "KABUL_KOMUTU: "
        return [line[len(prefix):] for line in str(objective).splitlines() if line.startswith(prefix)]

    @staticmethod
    def _objective_without_acceptance_commands(objective):
        prefix = "KABUL_KOMUTU: "
        return "\n".join(line for line in str(objective).splitlines() if not line.startswith(prefix))

    @classmethod
    def _acceptance_spec(cls, commands, cwd=None):
        payload = {"commands": [str(command) for command in commands], "cwd": str(Path(cwd or Path.cwd()).resolve())}
        return {**payload, "canonical_sha256": hashlib.sha256(cls._canonical(payload).encode("utf-8")).hexdigest()}

    @staticmethod
    def _objective_requires_executable(objective):
        normalized = unicodedata.normalize("NFKD", str(objective).casefold())
        normalized = "".join(character for character in normalized if not unicodedata.combining(character)).translate(str.maketrans({"ı": "i"}))
        return bool(re.search(r"\bexecutable\b|\bcalistirilabilir(?:\s+yap)?\b", normalized))

    @classmethod
    def _contract_clauses(cls, objective):
        normalized = cls._contract_text(objective)
        clauses = []
        for match in re.finditer(r"[^.!?;\n]+", normalized):
            raw = match.group(0)
            leading = len(raw) - len(raw.lstrip())
            content = raw.strip()
            if content:
                clauses.append({"index": len(clauses), "start": match.start() + leading, "content": content})
        return normalized, clauses

    @classmethod
    def _resolve_contract(cls, normalized, clauses, rules, default_mode, inherited=None):
        candidates = []
        for clause in clauses:
            for mode, rule, pattern, priority in rules:
                for match in re.finditer(pattern, clause["content"]):
                    candidates.append({"mode": mode, "rule": rule, "text": match.group(0), "clause_index": clause["index"], "clause": clause["content"][:PACKAGE_STRING_MAX], "start": clause["start"] + match.start(), "end": clause["start"] + match.end(), "priority": priority})
        effective = []
        for candidate in candidates:
            suppressed = False
            for other in candidates:
                if other is candidate or other["clause_index"] != candidate["clause_index"]:
                    continue
                contains = other["start"] <= candidate["start"] and other["end"] >= candidate["end"]
                more_specific = (other["end"] - other["start"], other["priority"]) > (candidate["end"] - candidate["start"], candidate["priority"])
                if contains and more_specific:
                    suppressed = True
                    break
            if not suppressed:
                effective.append(candidate)
        effective.sort(key=lambda item: (item["clause_index"], item["start"], item["end"], item["priority"], item["rule"]))
        if inherited:
            inherited_mode, inherited_rule = inherited
            winner = {"mode": inherited_mode, "rule": inherited_rule, "text": "inherited", "clause_index": len(clauses), "clause": "", "start": len(normalized), "end": len(normalized), "priority": 100}
            evidence_candidates = effective[-15:] + [winner]
            resolution = inherited_rule + "_override"
        elif effective:
            winner = effective[-1]
            evidence_candidates = effective[-16:]
            resolution = "last_explicit_directive"
        else:
            winner = None
            evidence_candidates = []
            resolution = "default_" + default_mode
        mode = winner["mode"] if winner else default_mode
        evidence = [{key: item[key] for key in ("mode", "rule", "text", "clause_index", "clause", "start", "end")} for item in evidence_candidates]
        return {"mode": mode, "winner": winner, "evidence": {"resolution": resolution, "candidate_count": len(effective) + int(bool(inherited)), "candidates": evidence, "winner": evidence[-1] if evidence else None}}

    @classmethod
    def _derive_task_policy(cls, objective, inherited_read_only=False, inherited_web_forbidden=False):
        read_rules = (
            ("write_allowed", "en_disable_read_only", r"\b(?:do\s+not|don['’]?t)\s+use\s+(?:the\s+)?read[\s-]+only(?:\s+mode)?\b", 30),
            ("write_allowed", "en_read_only_not_required", r"\bread[\s-]+only(?:\s+(?:mode|task))?\s+(?:is\s+)?not\s+(?:required|requested|enabled|wanted)\b", 30),
            ("write_allowed", "en_not_read_only_task", r"\b(?:this|the)\s+(?:task\s+)?is\s+not\s+(?:a\s+)?read[\s-]+only(?:\s+(?:task|mode))?\b", 30),
            ("write_allowed", "en_not_read_only", r"\bnot\s+(?:a\s+)?read[\s-]+only(?:\s+(?:task|mode))?\b", 25),
            ("write_allowed", "tr_not_read_only", r"\bsalt\s+okunur\s+(?:olmayan|degil|olmasin)(?:\s+(?:bir\s+)?(?:gorev|mod))?\b", 30),
            ("write_allowed", "en_make_changes", r"\b(?:make|apply)\s+(?:the\s+)?(?:file\s+)?changes?\b", 20),
            ("write_allowed", "en_write_files", r"\b(?:write|modify|change)\s+(?:(?:to|any|the)\s+){0,2}files?\b", 20),
            ("write_allowed", "tr_write_files", r"\b(?:dosyayi|dosyalari)\s+(?:degistir|yaz)\b", 20),
            ("write_allowed", "tr_make_changes", r"\bdegisiklik(?:leri)?\s+yap\b", 20),
            ("write_allowed", "tr_write_allowed", r"\byazilabilir\s+(?:bir\s+)?(?:gorev|mod)\b", 20),
            ("read_only", "tr_hicbir_dosya_degistirme", r"\bhicbir\s+dosyay?i?\s+degistirme(?:yin)?\b", 20),
            ("read_only", "tr_dosya_degistirme", r"\b(?:dosyayi|dosyalari)\s+(?:degistirme(?:yin)?|yazma(?:yin)?)\b", 20),
            ("read_only", "en_do_not_modify_files", r"\b(?:do\s+not|don['’]?t)\s+(?:modify|change|write)\s+(?:(?:any|the)\s+)?files?\b", 20),
            ("read_only", "en_no_file_changes", r"\b(?:make\s+)?no\s+file\s+changes?\b", 20),
            ("read_only", "tr_salt_okunur", r"\bsalt\s+okunur(?:\s+(?:bir\s+)?(?:gorev|mod|inceleme))?\b", 10),
            ("read_only", "en_read_only", r"\bread[\s-]+only(?:\s+(?:task|mode|review))?\b", 10),
        )
        network_rules = (
            ("web_forbidden", "tr_no_web_search", r"\bweb\s+aramasi\s+yapma(?:yin)?\b", 30),
            ("web_forbidden", "tr_no_web", r"\bwebi?\s+kullanma(?:yin)?\b", 30),
            ("web_forbidden", "tr_no_web_tools", r"\bweb_search\s*(?:(?:/|veya|ve)\s*)fetch_url\s+kullanma(?:yin)?\b", 35),
            ("web_forbidden", "en_no_web", r"\b(?:do\s+not|don['’]?t)\s+use\s+(?:the\s+)?(?:web(?:\s+search)?|web_search(?:\s*(?:/|or|and)\s*fetch_url)?)\b", 30),
            ("web_forbidden", "en_no_web_search", r"\bno\s+web\s+search\b", 30),
            ("web_allowed", "tr_use_web_search", r"\bweb\s+aramasi\s+yap\b", 20),
            ("web_allowed", "tr_use_web", r"\bwebi?\s+kullan\b", 20),
            ("web_allowed", "tr_search_internet", r"\binternetten\s+ara\b", 20),
            ("web_allowed", "en_web_search_allowed", r"\bweb\s+search\s+(?:is\s+)?allowed\b", 25),
            ("web_allowed", "en_use_web", r"\buse\s+(?:the\s+)?web(?:\s+search)?\b", 20),
            ("web_allowed", "en_search_web", r"\bsearch\s+(?:the\s+)?web\b", 20),
        )
        normalized, clauses = cls._contract_clauses(objective)
        read = cls._resolve_contract(normalized, clauses, read_rules, "write_allowed", ("read_only", "inherited_read_only") if inherited_read_only else None)
        network = cls._resolve_contract(normalized, clauses, network_rules, "web_allowed", ("web_forbidden", "inherited_web_forbidden") if inherited_web_forbidden else None)
        return {"mode": read["mode"], "read_only": read["mode"] == "read_only", "matched_rule": read["winner"]["rule"] if read["winner"] else None, "matched_text": read["winner"]["text"] if read["winner"] else "", "inherited_read_only": bool(inherited_read_only), "network_mode": network["mode"], "web_forbidden": network["mode"] == "web_forbidden", "network_matched_rule": network["winner"]["rule"] if network["winner"] else None, "network_matched_text": network["winner"]["text"] if network["winner"] else "", "inherited_web_forbidden": bool(inherited_web_forbidden), "parser_version": 3, "policy_evidence": read["evidence"], "network_policy_evidence": network["evidence"]}

    @staticmethod
    def _required_read_descriptor(value):
        if not isinstance(value, dict):
            return None
        path = value.get("path")
        digest = value.get("artifact_sha256")
        size_bytes = value.get("size_bytes")
        if not isinstance(path, str) or not path.startswith("/"):
            return None
        if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-fA-F]{64}", digest):
            return None
        if not isinstance(size_bytes, int) or isinstance(size_bytes, bool) or size_bytes < 0:
            return None
        canonical_path = str(Path(path).resolve())
        return {"path": canonical_path, "artifact_sha256": digest.lower(), "size_bytes": size_bytes, "required_group": str(value.get("required_group") or value.get("source_path") or canonical_path), "source_path": value.get("source_path"), "next_offset": int(value.get("next_offset", 0)), "complete": bool(value.get("complete", False)), "observed_sha256": value.get("observed_sha256"), "mismatch": value.get("mismatch", "")}

    @staticmethod
    def _required_write_descriptor(value):
        if not isinstance(value, dict) or not isinstance(value.get("path"), str) or not value["path"].startswith("/"):
            return None
        return {"path": str(Path(value["path"]).resolve()), "executable": bool(value.get("executable", False)), "complete": bool(value.get("complete", False))}

    def _normalize_required_writes(self):
        values = self.state.get("required_writes")
        if not isinstance(values, list):
            values = []
        normalized = []
        seen = set()
        for value in values:
            item = self._required_write_descriptor(value)
            if item is None or item["path"] in seen:
                continue
            seen.add(item["path"])
            normalized.append(item)
        self.state["required_writes"] = normalized

    def _normalize_required_write_targets(self):
        values = self.state.get("required_write_targets")
        if not isinstance(values, list):
            values = []
        normalized = []
        seen = set()
        for value in values:
            item = self._required_write_descriptor(value)
            if item is None or item["path"] in seen:
                continue
            seen.add(item["path"])
            normalized.append({"path": item["path"], "executable": item["executable"]})
        self.state["required_write_targets"] = normalized

    def _normalize_required_reads(self):
        values = self.state.get("required_reads")
        if not isinstance(values, list):
            values = []
        normalized = []
        seen = set()
        for value in values:
            item = self._required_read_descriptor(value)
            if item is None or item["path"] in seen:
                continue
            seen.add(item["path"])
            normalized.append(item)
        self.state["required_reads"] = normalized

    def _required_reads_for_objective(self, objective, task_policy=None):
        policy = task_policy if isinstance(task_policy, dict) else self.state.get("task_policy", {})
        if not policy.get("read_only"):
            return []
        reads = []
        for raw_path in sorted(self._explicit_absolute_paths(objective)):
            path = Path(raw_path).resolve()
            try:
                if not path.is_file():
                    continue
                raw = path.read_bytes()
            except OSError:
                continue
            reads.append({"path": str(path), "artifact_sha256": hashlib.sha256(raw).hexdigest(), "size_bytes": len(raw), "required_group": str(path), "source_path": str(path), "next_offset": 0, "complete": False, "observed_sha256": None, "mismatch": ""})
        return reads

    def _required_writes_for_objective(self, objective, task_policy=None):
        policy = task_policy if isinstance(task_policy, dict) else self.state.get("task_policy", {})
        if policy.get("read_only"):
            return []
        project_root = Path.cwd().resolve()
        executable = self._objective_requires_executable(objective)
        writes = []
        for raw_path in self._ordered_explicit_absolute_paths(objective):
            path = Path(raw_path).resolve()
            try:
                path.relative_to(project_root)
            except ValueError:
                continue
            try:
                if path.exists():
                    continue
            except OSError:
                continue
            writes.append({"path": str(path), "executable": executable, "complete": False})
        return writes

    def _refresh_required_read_phase(self):
        self._normalize_required_writes()
        self._normalize_required_reads()
        if self._next_required_write_descriptor() is not None:
            self.state["execution_phase"] = NEED_REQUIRED_WRITE
        elif self._next_required_read_descriptor() is not None:
            self.state["execution_phase"] = NEED_REQUIRED_READ
        elif self.state["required_writes"] or self.state["required_reads"]:
            self.state["execution_phase"] = NEED_FINISH
        else:
            self.state["execution_phase"] = None

    def _next_required_write_descriptor(self):
        return next((item for item in self.state.get("required_writes", []) if not item.get("complete")), None)

    def _required_write_next_call(self):
        descriptor = self._next_required_write_descriptor()
        if descriptor is None:
            return None
        return {"tool": "write", "filePath": descriptor["path"], "required_arguments": ["filePath", "content"]}

    def _required_read_status(self):
        reads = self.state.get("required_reads", [])
        groups = {item.get("required_group", item.get("path")): item.get("path") for item in reads}
        satisfied = {item.get("required_group", item.get("path")) for item in reads if item.get("complete")}
        remaining = [path for group, path in groups.items() if group not in satisfied]
        mismatches = [{key: item.get(key) for key in ("path", "artifact_sha256", "observed_sha256", "mismatch")} for item in reads if item.get("mismatch")]
        return remaining, mismatches

    def _next_required_read_descriptor(self):
        reads = self.state.get("required_reads", [])
        satisfied = {item.get("required_group", item.get("path")) for item in reads if item.get("complete")}
        return next((item for item in reads if not item.get("complete") and item.get("required_group", item.get("path")) not in satisfied), None)

    def _required_read_next_call(self):
        descriptor = self._next_required_read_descriptor()
        if descriptor is None:
            return None
        offset = int(descriptor.get("next_offset", 0))
        remaining = max(0, int(descriptor["size_bytes"]) - offset)
        return {"tool": "read", "filePath": descriptor["path"], "offset": offset, "limit": min(12000, max(1, remaining)), "remaining_bytes": remaining, "expected_sha256": descriptor["artifact_sha256"]}

    def _required_read_has_mismatch(self):
        return any(item.get("mismatch") for item in self.state.get("required_reads", []))

    def _required_write_block(self, name, args, reported_name=None):
        value = {"status": "required_write_phase_blocked", "tool": reported_name or name, "executed": False, "next_call": self._required_write_next_call()}
        if isinstance(args, dict) and "path" in args:
            value["path"] = args.get("path")
        self._persist("required_write_blocked", value)
        return value

    def _required_write_guard(self, name, args, reported_name=None):
        if self.state.get("execution_phase") != NEED_REQUIRED_WRITE:
            return None
        descriptor = self._next_required_write_descriptor()
        if name != "write_file" or descriptor is None or not isinstance(args, dict) or args.get("path") != descriptor["path"]:
            return self._required_write_block(name, args, reported_name=reported_name)
        return None

    def _advance_required_write(self, name, args, result):
        if name != "write_file" or self.state.get("execution_phase") != NEED_REQUIRED_WRITE or not isinstance(result, dict) or result.get("ok") is not True:
            return
        descriptor = self._next_required_write_descriptor()
        if descriptor is None or not isinstance(args, dict) or args.get("path") != descriptor["path"]:
            return
        path = Path(descriptor["path"])
        try:
            raw = path.read_bytes()
        except OSError as exc:
            self._persist("required_write_observation_failed", {"path": descriptor["path"], "error": repr(exc), "execution_phase": NEED_REQUIRED_WRITE})
            return
        digest = hashlib.sha256(raw).hexdigest()
        descriptor["complete"] = True
        self.state["required_reads"].append({"path": descriptor["path"], "artifact_sha256": digest, "size_bytes": len(raw), "required_group": descriptor["path"], "source_path": descriptor["path"], "next_offset": 0, "complete": False, "observed_sha256": None, "mismatch": ""})
        self._normalize_required_reads()
        self.state["execution_phase"] = NEED_REQUIRED_WRITE if self._next_required_write_descriptor() is not None else NEED_REQUIRED_READ
        self._persist("required_write_complete", {"path": descriptor["path"], "artifact_sha256": digest, "size_bytes": len(raw), "executable": bool(args.get("executable", False)), "execution_phase": self.state["execution_phase"]})

    def _required_read_block(self, name, reason, path=None, reported_name=None):
        remaining, mismatches = self._required_read_status()
        value = {"status": reason, "tool": reported_name or name, "executed": False, "required_reads": remaining, "mismatches": mismatches, "next_call": self._required_read_next_call()}
        if path is not None:
            value["path"] = path
        self._persist("required_read_blocked", value)
        return value

    def _required_read_guard(self, name, args, reported_name=None):
        phase = self.state.get("execution_phase")
        if phase == NEED_REQUIRED_READ:
            if name != "read_file":
                return self._required_read_block(name, "required_read_phase_blocked", reported_name=reported_name)
            raw_path = args.get("path") if isinstance(args, dict) else None
            descriptor = self._next_required_read_descriptor()
            if descriptor is None or raw_path != descriptor["path"]:
                return self._required_read_block(name, "required_read_path_blocked", raw_path, reported_name=reported_name)
            offset = args.get("offset")
            if not isinstance(offset, int) or isinstance(offset, bool) or offset != int(descriptor.get("next_offset", 0)):
                return self._required_read_block(name, "required_read_offset_blocked", raw_path, reported_name=reported_name)
        elif phase == NEED_FINISH and name != "finish_task":
            return self._required_read_block(name, "required_finish_phase_blocked", reported_name=reported_name)
        return None

    def _required_read_mismatch_finish_block(self, name, args):
        if name != "finish_task" or self.state.get("execution_phase") != NEED_FINISH or not self._required_read_has_mismatch():
            return None
        status = args.get("status") if isinstance(args, dict) else None
        decision = args.get("decision") if isinstance(args, dict) else None
        if status != "completed" and decision != "approved":
            return None
        remaining, mismatches = self._required_read_status()
        blocked = {"status": "required_read_mismatch_finish_blocked", "tool": name, "executed": False, "required_reads": remaining, "mismatches": mismatches}
        self._persist("required_read_mismatch_finish_blocked", blocked)
        return blocked

    def _advance_required_read(self, name, args, result):
        if name != "read_file" or self.state.get("execution_phase") != NEED_REQUIRED_READ or not isinstance(result, dict) or result.get("status") in {"required_read_phase_blocked", "required_read_path_blocked", "required_read_offset_blocked"}:
            return
        try:
            path = str(Path(args["path"]).resolve())
        except (KeyError, TypeError, ValueError):
            return
        descriptor = self._next_required_read_descriptor()
        if descriptor is None or descriptor.get("path") != path:
            return
        if result.get("status") == "required_read_observation_failed":
            descriptor["complete"] = True
            descriptor["observed_sha256"] = ""
            descriptor["mismatch"] = "required_read_observation_failed"
            self.state["execution_phase"] = NEED_FINISH
            self._persist("required_read_complete", {"path": path, "expected_sha256": descriptor["artifact_sha256"], "observed_sha256": "", "mismatch": descriptor["mismatch"], "execution_phase": NEED_FINISH})
            return
        next_offset = int(result.get("next_offset", int(args.get("offset", 0))))
        if result.get("has_more"):
            descriptor["next_offset"] = next_offset
            self._persist("required_read_continuation", {"path": path, "next_offset": next_offset})
            return
        try:
            raw = Path(path).read_bytes()
            observed_sha = hashlib.sha256(raw).hexdigest()
            observed_size = len(raw)
        except OSError as exc:
            observed_sha = ""
            observed_size = -1
            descriptor["mismatch"] = "read_verification_error:" + repr(exc)
        descriptor["next_offset"] = next_offset
        descriptor["complete"] = True
        descriptor["observed_sha256"] = observed_sha
        if observed_size != descriptor["size_bytes"] or observed_sha != descriptor["artifact_sha256"] or next_offset != observed_size:
            descriptor["mismatch"] = "required_hash_or_size_mismatch"
        groups = {item.get("required_group", item.get("path")) for item in self.state.get("required_reads", [])}
        satisfied = {item.get("required_group", item.get("path")) for item in self.state.get("required_reads", []) if item.get("complete")}
        if groups.issubset(satisfied):
            self.state["execution_phase"] = NEED_FINISH
        self._persist("required_read_complete", {"path": path, "expected_sha256": descriptor["artifact_sha256"], "observed_sha256": observed_sha, "mismatch": descriptor.get("mismatch", ""), "execution_phase": self.state.get("execution_phase")})

    def set_task(self, objective, acceptance_commands=None):
        self.state["objective"] = objective
        self.state["completed"] = False
        self.state["terminal"] = False
        self.state["success"] = False
        self.state["last_tool_signature"] = None
        self.state["non_idempotent_calls"] = {}
        self.state["task_policy"] = self._derive_task_policy(objective, inherited_read_only=self.inherited_read_only, inherited_web_forbidden=self.inherited_web_forbidden)
        if self.state.get("role") == "caller":
            commands = [str(command) for command in (acceptance_commands or [])]
            commands.extend(self._objective_acceptance_commands(objective))
            self.state["acceptance_spec"] = self._acceptance_spec(commands)
            self.state["acceptance_runs"] = []
        if self.state.get("role") != "caller" and self.state.get("subagent_role") not in {"reviewer", "interaction"}:
            self.state["required_writes"] = self._required_writes_for_objective(objective)
            self.state["required_write_targets"] = [{"path": item["path"], "executable": item["executable"]} for item in self.state["required_writes"]]
            self.state["required_reads"] = self._required_reads_for_objective(objective)
            self._refresh_required_read_phase()
        else:
            self.state["required_writes"] = []
            self.state["required_write_targets"] = []
            self._refresh_required_read_phase()
        self._persist("task_policy", self.state["task_policy"])
        self._message({"role": "user", "content": objective})

    @staticmethod
    def _network_upgrade_source(content, policy):
        raw = str(content).encode("utf-8")
        return {"source_sha256": hashlib.sha256(raw).hexdigest(), "source_size_bytes": len(raw), "matched_rule": policy.get("network_matched_rule"), "matched_text": policy.get("network_matched_text", "")[:PACKAGE_STRING_MAX]}

    def _upgraded_network_policy(self, state, source, transition):
        current = state.get("task_policy") if isinstance(state.get("task_policy"), dict) else {}
        upgraded = self._derive_task_policy(state.get("objective", ""), inherited_read_only=bool(current.get("read_only")), inherited_web_forbidden=True)
        upgraded["transition"] = transition
        upgraded["previous_network_mode"] = current.get("network_mode", "web_allowed")
        upgraded["network_policy_evidence"]["upgrade_source"] = safe_json(source)
        return upgraded

    def _upgrade_network_contract(self, content):
        detected = self._derive_task_policy(content)
        if not detected.get("web_forbidden"):
            return False
        source = self._network_upgrade_source(content, detected)
        self.inherited_web_forbidden = True
        self.state["task_policy"] = self._upgraded_network_policy(self.state, source, "user_interrupt_network_upgrade")
        self._persist("network_policy_upgrade", {"task_id": self.state.get("session_id"), "task_policy": self.state["task_policy"], "source": source})
        notice = self._canonical({"type": "network_policy_upgrade", "web_forbidden": True, "source": source, "instruction": "web_search ve fetch_url kullanma"})
        records = self._descendant_records()
        wake_records = []
        for record in records:
            journal = record["journal"]
            descendant_state = journal.load_state() or record["state"]
            descendant_state["task_policy"] = self._upgraded_network_policy(descendant_state, source, "inherited_interrupt_network_upgrade")
            pending = descendant_state.setdefault("pending_user", [])
            if notice not in pending:
                pending.append(notice)
            journal.transaction("network_policy_upgrade", {"task_id": record["node"].get("task_id"), "task_policy": descendant_state["task_policy"], "source": source}, descendant_state)
            record["node"]["task_policy"] = safe_json(descendant_state["task_policy"])
            wake_records.append(record)
        self._persist("network_policy_tree_upgrade", {"source": source, "upgraded_task_ids": [record["node"].get("task_id") for record in records]})
        for record in wake_records:
            node = record["node"]
            try:
                pid = int(node.get("pid"))
            except (TypeError, ValueError):
                record["journal"].event("network_policy_wake", {"task_id": node.get("task_id"), "action": "pid_missing"})
                continue
            expected = node.get("identity") if isinstance(node.get("identity"), dict) else {}
            actual = proc_identity(pid)
            if not expected or not identity_matches(expected, actual):
                record["journal"].event("network_policy_wake", {"task_id": node.get("task_id"), "pid": pid, "action": "identity_mismatch", "actual": actual})
                continue
            try:
                os.kill(pid, signal.SIGUSR1)
                record["journal"].event("network_policy_wake", {"task_id": node.get("task_id"), "pid": pid, "action": "sigusr1_sent", "identity": expected})
            except OSError as exc:
                record["journal"].event("network_policy_wake", {"task_id": node.get("task_id"), "pid": pid, "action": "signal_error", "error": repr(exc)})
        return True

    def user_message(self, content):
        self._upgrade_network_contract(content)
        self.state["pending_user"].append(content)
        self._persist("user_interrupt", {"content": content})
        self._wake()

    def pause(self):
        self.state["pause"] = True
        self._persist("pause", {})

    def resume(self):
        self.state["pause"] = False
        self._persist("resume", {})
        self._wake()

    def shutdown(self):
        self.state["shutdown"] = True
        self._persist("shutdown", {})
        with self.connection_lock:
            connection = self.active_connection
        if connection:
            self._close_connection(connection)
        self._cleanup_descendant_tree("explicit_shutdown")
        self._wake()

    def wake(self, *_):
        self.wake_requested.set()
        with self.connection_lock:
            connection = self.active_connection
        if connection:
            self._close_connection(connection)
        self._wake()

    @staticmethod
    def _close_connection(connection):
        try:
            if connection.sock:
                connection.sock.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        try:
            connection.close()
        except OSError:
            pass

    def _reload_external_state(self):
        fresh = self.journal.load_state()
        if fresh:
            for key in ("pending_user", "working_state", "subagent_result", "pause", "shutdown", "task_policy"):
                if key in fresh:
                    self.state[key] = fresh[key]
            policy = self.state.get("task_policy", {})
            self.inherited_read_only = bool(self.inherited_read_only or policy.get("inherited_read_only") or policy.get("matched_rule") == "inherited_read_only")
            self.inherited_web_forbidden = bool(self.inherited_web_forbidden or policy.get("inherited_web_forbidden") or policy.get("network_matched_rule") == "inherited_web_forbidden")

    def _wake(self):
        with self.condition:
            self.condition.notify_all()

    def _checkpoint(self):
        with self.condition:
            while self.state["pause"] and not self.state["shutdown"]:
                self.condition.wait()
        if self.state["shutdown"]:
            raise InterruptedError("shutdown")

    def _recover_pending(self):
        for pending in list(self.state.get("pending_tool_calls", [])):
            if pending["name"] in IDEMPOTENT:
                value = self.dispatch(pending["name"], pending["arguments"], recovering=True)
                outcome = "replayed_read"
            else:
                value = {"ok": False, "status": "unknown_outcome", "message": "Önceki çağrı kesildi; yan etki yeniden yürütülmedi. Gerçek durumu araçlarla doğrula."}
                outcome = "unknown_outcome"
            self._complete_tool(pending, value, outcome)

    def _complete_tool(self, pending, value, outcome="completed"):
        self.state["pending_tool_calls"] = [item for item in self.state["pending_tool_calls"] if item["id"] != pending["id"]]
        self.state["completed_tool_calls"].append({"id": pending["id"], "outcome": outcome})
        package = self._result_package(pending["name"], value, outcome, record_id=pending["id"])
        if self.state.get("role") == "subagent" and pending["name"] in WORKER_RESULT_TOOLS:
            package = self._fit_worker_result(pending, value, package)
        self.state["result_packages"].append(package)
        self._persist("completed_tool_call", {"id": pending["id"], "outcome": outcome, "result_package": package})
        self._message({"role": "tool", "tool_call_id": pending["id"], "name": pending["name"], "content": json.dumps(package, ensure_ascii=False, sort_keys=True)})

    def _next_result_order(self):
        value = int(self.state.get("result_sequence", 0))
        self.state["result_sequence"] = value + 1
        return value

    def _result_package(self, tool, value, outcome="completed", record_id=None, record_order=None, compact_override=None):
        raw = json.dumps(safe_json(value), ensure_ascii=False, sort_keys=True)
        raw_bytes = raw.encode("utf-8")
        digest = hashlib.sha256((tool + raw).encode("utf-8")).hexdigest()
        artifact = self.journal.root / "artifacts" / (digest + ".json")
        ensure_dir(artifact.parents[0])
        artifact.write_bytes(raw_bytes)
        artifact_descriptor = {"artifact_ref": str(artifact), "artifact_sha256": hashlib.sha256(raw_bytes).hexdigest(), "size_bytes": len(raw_bytes)}
        if compact_override is not None:
            compact = compact_override
        elif self.state.get("role") == "subagent" and tool in WORKER_RESULT_TOOLS:
            compact = value
        elif len(raw_bytes) <= RESULT_INLINE_BYTES:
            compact = value
        elif isinstance(value, dict):
            compact = {**artifact_descriptor, "fields": sorted(value)}
        else:
            compact = {**artifact_descriptor, "value_type": type(value).__name__}
        finish_fields = "status, decision ve summary" if self.state.get("subagent_role") in {"reviewer", "interaction"} else "status ve summary"
        if tool == "read":
            next_actions = ["read has_more=false ise aynı filePath'i tekrar okuma; finish_task için yalnız " + finish_fields + " gönder."]
        elif tool == "read_file":
            next_actions = ["read_file has_more=false ise aynı path'i tekrar okuma; finish_task için yalnız " + finish_fields + " gönder."]
        else:
            next_actions = []
